 const Topics = module.exports;

+Topics.lockPosting = async function (req, error) {
+	const id = req.uid || req.sessionID;
+	if (!id) {
+		throw new Error('[[error:invalid-data]]');
+	}
+
+	const lockKey = `posting:${id}`;
+	const locked = await db.setnx(lockKey, '1');
+	if (!locked) {
+		throw new Error(error);
+	}
+
+	// Set a timeout to automatically release the lock after 30 seconds
+	// to prevent deadlocks if the process crashes
+	setTimeout(async () => {
+		try {
+			await db.delete(lockKey);
+		} catch (err) {
+			// Ignore errors during cleanup
+		}
+	}, 30000);
+
+	return lockKey;
+};
+
