@@ -0,0 +1,83 @@
+'use strict';
+
+const nconf = require('nconf');
+const user = require('../user');
+const privileges = require('../privileges');
+
+const wellKnownController = module.exports;
+
+wellKnownController.webfinger = async function (req, res) {
+	const { resource } = req.query;
+	if (!resource) {
+		return res.status(400).json({ error: '[[error:invalid-resource]]' });
+	}
+
+	// Validate resource parameter
+	if (!resource.startsWith('acct:')) {
+		return res.status(400).json({ error: '[[error:invalid-resource]]' });
+	}
+
+	// Extract username from resource (acct:username@hostname)
+	const atIndex = resource.lastIndexOf('@');
+	if (atIndex === -1) {
+		return res.status(400).json({ error: '[[error:invalid-resource]]' });
+	}
+
+	const username = resource.substring(5, atIndex); // Remove 'acct:' prefix
+	const hostname = resource.substring(atIndex + 1);
+
+	// Validate hostname matches the configured URL
+	const expectedHostname = nconf.get('url_parsed').hostname;
+	if (hostname !== expectedHostname) {
+		return res.status(400).json({ error: '[[error:invalid-resource]]' });
+	}
+
+	// Check if user has permission to view users
+	const canViewUsers = await privileges.global.can('view:users', req.uid);
+	if (!canViewUsers) {
+		return res.status(403).json({ error: '[[error:invalid-privileges]]' });
+	}
+
+	// Resolve username to uid
+	const uid = await user.getUidByUsername(username);
+	if (!uid) {
+		return res.status(404).json({ error: '[[error:no-user]]' });
+	}
+
+	// Verify user exists
+	const exists = await user.exists(uid);
+	if (!exists) {
+		return res.status(404).json({ error: '[[error:no-user]]' });
+	}
+
+	// Get user data
+	const userData = await user.getUserData(uid);
+
+	const { userslug } = userData;
+
+	// Build aliases
+	const aliases = [
+		`urn:uuid:${uid}`,
+		`${nconf.get('url')}/user/${userslug}`,
+	];
+
+	// Build links
+	const links = [
+		{
+			rel: 'http://webfinger.net/rel/profile-page',
+			type: 'text/html',
+			href: `${nconf.get('url')}/user/${userslug}`,
+		},
+	];
+
+	// Return webfinger response
+	res.json({
+		subject: resource,
+		aliases: aliases,
+		links: links,
+	});
+};
+
+wellKnownController.changePassword = function (req, res) {
+	res.redirect('/me/edit/password');
+};
