diff --git a/src/upgrades/1.19.3/rename_post_upload_hashes.js b/src/upgrades/1.19.3/rename_post_upload_hashes.js
new file mode 100644
index 000000000..6e6747e3a
--- /dev/null
+++ b/src/upgrades/1.19.3/rename_post_upload_hashes.js
@@ -0,0 +1,78 @@
+'use strict';
+
+const nconf = require('nconf');
+const crypto = require('crypto');
+
+const db = require('../../database');
+
+module.exports = {
+	name: 'Rename object and sorted sets used in post uploads',
+	timestamp: Date.UTC(2022, 1, 10),
+	method: async function (context) {
+		const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');
+
+		// Get all post IDs that have uploads
+		const pids = await db.getSortedSetRange('posts:pid', 0, -1);
+		context.log(`Found ${pids.length} posts with uploads`);
+
+		// Process in batches
+		const batch = require('../../batch');
+		await batch.processArray(pids, async (pid) => {
+			// Get current uploads for this post
+			const uploads = await db.getSortedSetMembers(`post:${pid}:uploads`);
+
+			if (!uploads.length) {
+				return;
+			}
+
+			// Build new paths with "files/" prefix
+			const newUploads = uploads.map(upload => 
+				upload.startsWith('files/') ? upload : `files/${upload}`
+			);
+
+			// Update post uploads sorted set
+			await db.sortedSetRemove(`post:${pid}:uploads`, uploads);
+			await db.sortedSetAdd(`post:${pid}:uploads`, Array(newUploads.length).fill(Date.now()), newUploads);
+
+			// Update reverse mappings
+			const oldKeys = uploads.map(upload => `upload:${md5(upload)}:pids`);
+			const newKeys = newUploads.map(upload => `upload:${md5(upload)}:pids`);
+
+			// For each old key, move the data to the new key
+			for (let i = 0; i < uploads.length; i++) {
+				if (oldKeys[i] !== newKeys[i]) {
+					// Get all pids associated with this upload
+					const pidsList = await db.getSortedSetRange(oldKeys[i], 0, -1);
+					
+					if (pidsList.length) {
+						// Remove from old key
+						await db.sortedSetRemove(oldKeys[i], pidsList);
+						
+						// Add to new key
+						const scores = pidsList.map(() => Date.now());
+						await db.sortedSetAdd(newKeys[i], scores, pidsList);
+					}
+				}
+			}
+
+			// Update upload size objects
+			for (let i = 0; i < uploads.length; i++) {
+				if (oldKeys[i] !== newKeys[i]) {
+					const sizeKey = `upload:${md5(uploads[i])}`;
+					const newSizeKey = `upload:${md5(newUploads[i])}`;
+					
+					const sizeData = await db.getObject(sizeKey);
+					if (sizeData) {
+						await db.delete(sizeKey);
+						await db.setObject(newSizeKey, sizeData);
+					}
+				}
+			}
+		}, {
+			batch: 50,
+			log: context.log,
+		});
+
+		context.log('Post upload hashes renamed successfully');
+	},
+};

