+
+import { KeyboardEvent as ReactKeyboardEvent } from 'react';
+
+/**
+ * Represents a keyboard shortcut as a combination of a key and modifier options.
+ */
+export interface KeyCombo {
+    key: string;
+    ctrlKey?: boolean;
+    altKey?: boolean;
+    shiftKey?: boolean;
+    metaKey?: boolean;
+    ctrlOrCmd?: boolean;
+}
+
+/**
+ * Determines whether a keyboard event matches the given key combination.
+ * Handles exact modifier matching, capitalization and Shift, and interprets
+ * `ctrlOrCmd` differently for macOS versus other platforms.
+ *
+ * @param ev - The keyboard event to check
+ * @param combo - The key combination to match against
+ * @param onMac - Whether the current platform is macOS
+ * @returns true if the event matches the key combination, false otherwise
+ */
+export function isKeyComboMatch(
+    ev: KeyboardEvent | ReactKeyboardEvent,
+    combo: KeyCombo,
+    onMac: boolean,
+): boolean {
+    // Normalize the key for comparison (case-insensitive for letter keys)
+    const evKey = ev.key.length === 1 ? ev.key.toLowerCase() : ev.key;
+    const comboKey = combo.key.length === 1 ? combo.key.toLowerCase() : combo.key;
+
+    // Check the key
+    if (evKey !== comboKey) {
+        return false;
+    }
+
+    // Determine which modifier keys should be pressed based on the combo
+    let expectedCtrl = combo.ctrlKey || false;
+    let expectedAlt = combo.altKey || false;
+    let expectedShift = combo.shiftKey || false;
+    let expectedMeta = combo.metaKey || false;
+
+    // Handle ctrlOrCmd: if set, it overrides ctrlKey/metaKey for the target platform
+    if (combo.ctrlOrCmd) {
+        if (onMac) {
+            expectedMeta = true;
+            expectedCtrl = false; // Don't check ctrlKey when ctrlOrCmd is set on macOS
+        } else {
+            expectedCtrl = true;
+            expectedMeta = false; // Don't check metaKey when ctrlOrCmd is set on non-macOS
+        }
+    }
+
+    // Check that all expected modifiers are pressed
+    if (ev.ctrlKey !== expectedCtrl) return false;
+    if (ev.altKey !== expectedAlt) return false;
+    if (ev.shiftKey !== expectedShift) return false;
+    if (ev.metaKey !== expectedMeta) return false;
+
+    // Check that no extra modifiers are pressed
+    // If a modifier is not expected but is pressed, return false
+    if (ev.ctrlKey && !expectedCtrl) return false;
+    if (ev.altKey && !expectedAlt) return false;
+    if (ev.shiftKey && !expectedShift) return false;
+    if (ev.metaKey && !expectedMeta) return false;
+
+    return true;
+}

