+distributed under the License is distributed on an "AS IS" BASIS,
+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import React, { useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Field from '../../elements/Field';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName?: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [isEditing, setIsEditing] = useState(false);
+    const [deviceName, setDeviceName] = useState(device.display_name ?? '');
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string | null>(null);
+
+    const handleRenameClick = () => {
+        setIsEditing(true);
+        setError(null);
+    };
+
+    const handleSave = async () => {
+        if (!saveDeviceName || !device.device_id) {
+            return;
+        }
+
+        setIsSaving(true);
+        setError(null);
+
+        try {
+            await saveDeviceName(device.device_id, deviceName);
+            setIsEditing(false);
+            setIsSaving(false);
+        } catch (err) {
+            setError("Failed to set display name.");
+            setIsSaving(false);
+        }
+    };
+
+    const handleCancel = () => {
+        setDeviceName(device.display_name ?? '');
+        setIsEditing(false);
+        setError(null);
+    };
+
+    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
+        setDeviceName(e.target.value);
+    };
+
+    const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
+        if (e.key === 'Enter') {
+            handleSave();
+        } else if (e.key === 'Escape') {
+            handleCancel();
+        }
+    };
+
+    if (isEditing) {
+        return (
+            <div className='mx_DeviceDetailHeading' data-testid='device-detail-heading-edit'>
+                <Field
+                    id='device-display-name'
+                    label={_t('Session name')}
+                    value={deviceName}
+                    onChange={handleInputChange}
+                    onKeyPress={handleKeyPress}
+                    placeholder={device.device_id}
+                    maxLength={100}
+                    autoFocus={true}
+                />
+                { error && <div className='mx_DeviceDetailHeading_error' data-testid='device-detail-heading-error'>{ error }</div> }
+                <div className='mx_DeviceDetailHeading_actions'>
+                    <AccessibleButton
+                        kind='primary_sm'
+                        onClick={handleSave}
+                        disabled={isSaving}
+                        data-testid='device-detail-heading-save'
+                    >
+                        { _t('Save') }
+                    </AccessibleButton>
+                    <AccessibleButton
+                        kind='cancel_sm'
+                        onClick={handleCancel}
+                        disabled={isSaving}
+                        data-testid='device-detail-heading-cancel'
+                    >
+                        { _t('Cancel') }
+                    </AccessibleButton>
+                </div>
+                <div className='mx_DeviceDetailHeading_notice' data-testid='device-detail-heading-notice'>
+                    { _t('Session names are visible to other people you communicate with.') }
+                </div>
+            </div>
+        );
+    }
+
+    return (
+        <div className='mx_DeviceDetailHeading' data-testid='device-detail-heading-read'>
+            <h3 className='mx_Heading_h3' data-testid='device-detail-heading-name'>
+                { device.display_name ?? device.device_id }
+            </h3>
+            { saveDeviceName && (
+                <AccessibleButton
+                    kind='link_inline'
+                    onClick={handleRenameClick}
+                    data-testid='device-detail-heading-rename'
+                >
+                    { _t('Rename') }
+                </AccessibleButton>
+            ) }
+        </div>
+    );
+};
+
+export default DeviceDetailHeading;
