+
+import { useState, useEffect, useCallback } from "react";
+
+import UIStore, { UI_EVENTS } from "../stores/UIStore";
+
+/**
+ * Hook to get the current window width and update it when the window is resized
+ * @returns The current window width
+ */
+export default function useWindowWidth(): number {
+    const [windowWidth, setWindowWidth] = useState<number>(UIStore.instance.windowWidth);
+
+    const handler = useCallback((): void => {
+        setWindowWidth(UIStore.instance.windowWidth);
+    }, []);
+
+    // Use useEffect to manage the event listener lifecycle
+    useEffect(() => {
+        // Add event listener
+        UIStore.instance.on(UI_EVENTS.Resize, handler);
+
+        // Remove event listener on cleanup
+        return () => {
+            UIStore.instance.off(UI_EVENTS.Resize, handler);
+        };
+    }, [handler]);
+
+    return windowWidth;
+}

