diff --git a/src/components/views/rooms/EventPreview.tsx b/src/components/views/rooms/EventPreview.tsx
new file mode 100644
index 0000000000..d1da3984b2
--- /dev/null
+++ b/src/components/views/rooms/EventPreview.tsx
@@ -0,0 +1,211 @@
+/*
+ * Copyright 2024 New Vector Ltd.
+ * Copyright 2024 The Matrix.org Foundation C.I.C.
+ *
+ * SPDX-License-Identifier: AGPL-3.0-only OR GPL-3.0-only
+ * Please see LICENSE files in the repository root for full details.
+ */
+
+import React, { JSX, useEffect, useState } from "react";
+import { MatrixEvent, MatrixEventEvent, MsgType } from "matrix-js-sdk/src/matrix";
+import { useAsyncMemo } from "../../../hooks/useAsyncMemo";
+import { _t } from "../../../languageHandler";
+import { MessagePreviewStore } from "../../../stores/room-list/MessagePreviewStore";
+
+/**
+ * A tuple representing the preview text and optional prefix.
+ */
+export type Preview = [preview: string, prefix: string | null];
+
+/**
+ * The props for the {@link EventPreview} component.
+ */
+interface EventPreviewProps {
+    /**
+     * The event to display the preview for
+     */
+    mxEvent: MatrixEvent;
+    /**
+     * Optional CSS classes for styling
+     */
+    className?: string;
+    /**
+     * Additional props passed to the child EventPreviewTile
+     */
+    [key: string]: unknown;
+}
+
+/**
+ * The props for the {@link EventPreviewTile} component.
+ */
+interface EventPreviewTileProps {
+    /**
+     * The preview text and optional prefix
+     */
+    preview: Preview;
+    /**
+     * Optional CSS classes for styling
+     */
+    className?: string;
+    /**
+     * Additional props passed to the outer span element
+     */
+    [key: string]: unknown;
+}
+
+/**
+ * A component that displays a preview for an event with optional type prefix.
+ * @param preview - A tuple [previewText, prefix] representing the preview text and optional prefix
+ * @param className - Optional CSS classes for styling
+ * @param props - Additional props passed to the outer span element
+ * @returns The rendered React element (a span) or null
+ */
+export function EventPreviewTile({ preview, className, ...props }: EventPreviewTileProps): JSX.Element | null {
+    const [previewText, prefix] = preview;
+
+    if (!previewText) return null;
+
+    if (!prefix) {
+        return (
+            <span className={className} {...props}>
+                {previewText}
+            </span>
+        );
+    }
+
+    return (
+        <span className={className} {...props}>
+            {_t("event_preview|prefix_format", { prefix, preview: previewText }, { bold: (sub) => <span className="mx_EventPreview_prefix">{sub}</span> })}
+        </span>
+    );
+}
+
+/**
+ * Hook to generate a preview string and optional message type prefix for a given MatrixEvent.
+ * @param mxEvent - The event object for which to generate the preview
+ * @returns A tuple [previewText, prefix] or null if no preview can be generated
+ */
+export function useEventPreview(mxEvent: MatrixEvent | undefined): Preview | null {
+    const [content, setContent] = useState(mxEvent?.getContent());
+    const [isRedacted, setIsRedacted] = useState(mxEvent?.isRedacted());
+    const [isDecryptionFailure, setIsDecryptionFailure] = useState(mxEvent?.isDecryptionFailure());
+    const [replacingEventId, setReplacingEventId] = useState(mxEvent?.replacingEventId());
+
+    // Track content changes due to edits
+    useEffect(() => {
+        if (!mxEvent) return;
+        const onEventReplaced = (): void => {
+            setContent(mxEvent.getContent());
+            setReplacingEventId(mxEvent.replacingEventId());
+        };
+        mxEvent.on(MatrixEventEvent.Replaced, onEventReplaced);
+        return () => {
+            mxEvent.off(MatrixEventEvent.Replaced, onEventReplaced);
+        };
+    }, [mxEvent]);
+
+    // Track decryption changes
+    useEffect(() => {
+        if (!mxEvent) return;
+        const onDecrypted = (): void => {
+            setContent(mxEvent.getContent());
+            setIsRedacted(mxEvent.isRedacted());
+            setIsDecryptionFailure(mxEvent.isDecryptionFailure());
+        };
+        mxEvent.on(MatrixEventEvent.Decrypted, onDecrypted);
+        return () => {
+            mxEvent.off(MatrixEventEvent.Decrypted, onDecrypted);
+        };
+    }, [mxEvent]);
+
+    // Track redaction changes
+    useEffect(() => {
+        if (!mxEvent) return;
+        const onUpdate = (): void => {
+            setIsRedacted(mxEvent.isRedacted());
+        };
+        mxEvent.on(MatrixEventEvent.BeforeRedaction, onUpdate);
+        mxEvent.on(MatrixEventEvent.Redacted, onUpdate);
+        return () => {
+            mxEvent.off(MatrixEventEvent.BeforeRedaction, onUpdate);
+            mxEvent.off(MatrixEventEvent.Redacted, onUpdate);
+        };
+    }, [mxEvent]);
+
+    return useAsyncMemo(async (): Promise<Preview | null> => {
+        if (!mxEvent || isRedacted || isDecryptionFailure) {
+            return null;
+        }
+
+        // Check if the event is being decrypted
+        if (mxEvent.isBeingDecrypted()) {
+            return null;
+        }
+
+        // Generate the preview text using MessagePreviewStore
+        const previewText = MessagePreviewStore.instance.generatePreviewForEvent(mxEvent);
+        
+        if (!previewText) {
+            return null;
+        }
+
+        // Get the prefix based on message type
+        const prefix = getEventPreviewPrefix(mxEvent);
+
+        return [previewText, prefix];
+    }, [mxEvent, content, isRedacted, isDecryptionFailure, replacingEventId]);
+}
+
+/**
+ * Get the prefix for the event preview based on the event type and message type.
+ * @param mxEvent - The event to get the prefix for
+ * @returns The prefix string or null if no prefix should be shown
+ */
+function getEventPreviewPrefix(mxEvent: MatrixEvent): string | null {
+    const type = mxEvent.getType();
+    const content = mxEvent.getContent();
+    const msgType = content?.msgtype as MsgType;
+
+    // Polls
+    if (type === "m.poll.start" || type === "org.matrix.msc3381.poll.start") {
+        return _t("event_preview|prefix|poll");
+    }
+
+    // Stickers - don't prefix, they have their own name rendering
+    if (type === "m.sticker") {
+        return null;
+    }
+
+    // Plain text - no prefix
+    if (!msgType || msgType === MsgType.Text || msgType === MsgType.Emote || msgType === MsgType.Notice) {
+        return null;
+    }
+
+    // Other message types
+    switch (msgType) {
