+
+import { logger } from 'matrix-js-sdk/src/logger';
+import SettingsStore from '../../settings/SettingsStore';
+
+/**
+ * Public listener for HTMLMediaElement events. Dispatches by e.type:
+ * - Logs structured errors (with element id) for error-class events
+ * - Logs debug messages for debug-class events only when the "debug_legacy_call_handler" setting is enabled
+ * - Ignores others
+ * 
+ * Safe to attach directly to media elements.
+ * 
+ * @param e - The HTMLMediaElement event to handle
+ */
+export function handleEvent(e: Event): void {
+    const target = e.target as HTMLMediaElement | null;
+    const elementId = target?.id || 'unknown';
+    
+    switch (e.type) {
+        case 'error':
+            // Log structured errors with element id for error-class events
+            logger.error(`LegacyCallHandler media element error [element id=${elementId}]`, e);
+            break;
+        case 'loadeddata':
+        case 'loadedmetadata':
+        case 'stalled':
+        case 'waiting':
+        case 'playing':
+        case 'pause':
+        case 'ended':
+            // Log debug messages for debug-class events only when the setting is enabled
+            if (SettingsStore.getValue('debug_legacy_call_handler')) {
+                logger.debug(`LegacyCallHandler media element event [element id=${elementId}, event type=${e.type}]`, e);
+            }
+            break;
+        default:
+            // Ignore other events
+            break;
+    }
+}
