+Unless required by applicable law or agreed to in writing, software
+distributed under the License is distributed on an "AS IS" BASIS,
+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { MatrixClient } from "matrix-js-sdk/src/client";
+import { MatrixEvent } from "matrix-js-sdk/src/models/event";
+import { RelationType } from "matrix-js-sdk/src/matrix";
+import { logger } from "matrix-js-sdk/src/logger";
+
+import { VoiceBroadcastInfoEventType, VoiceBroadcastInfoState, VoiceBroadcastRecording } from "..";
+import { VoiceBroadcastRecordingsStore } from "../stores";
+
+const TIMEOUT_MS = 10000; // 10 seconds
+
+/**
+ * Starts a new voice broadcast by sending an initial state event, waiting for
+ * its confirmation in room state, creating a VoiceBroadcastRecording, setting
+ * it as current in the store, and returning the event.
+ * 
+ * @param client The Matrix client.
+ * @param roomId The room ID where the broadcast should start.
+ * @returns A promise that resolves with the state event.
+ */
+export async function startNewVoiceBroadcastRecording(
+    client: MatrixClient,
+    roomId: string,
+): Promise<MatrixEvent> {
+    const userId = client.getUserId();
+    if (!userId) {
+        throw new Error("User is not logged in");
+    }
+
+    // Send the initial state event
+    const stateEvent = await client.sendStateEvent(
+        roomId,
+        VoiceBroadcastInfoEventType,
+        {
+            state: VoiceBroadcastInfoState.Started,
+            chunk_length: 0,
+        },
+        userId,
+    );
+
+    logger.log(`Voice broadcast started with event ${stateEvent.event_id} in room ${roomId}`);
+
+    // Wait for the event to appear in room state
+    const room = client.getRoom(roomId);
+    if (!room) {
+        throw new Error(`Room ${roomId} not found`);
+    }
+
+    const startTime = Date.now();
+    while (Date.now() - startTime < TIMEOUT_MS) {
+        const currentStateEvent = room.currentState.getStateEvents(VoiceBroadcastInfoEventType, userId);
+        if (currentStateEvent && currentStateEvent.getId() === stateEvent.event_id) {
+            logger.log(`Voice broadcast state event confirmed in room state: ${stateEvent.event_id}`);
+            break;
+        }
+        // Wait a bit before checking again
+        await new Promise(resolve => setTimeout(resolve, 100));
+    }
+
+    // Create a VoiceBroadcastRecording instance
+    const infoEvent = new MatrixEvent(stateEvent);
+    const recording = VoiceBroadcastRecordingsStore.instance.getOrCreateRecording(
+        client,
+        infoEvent,
+        VoiceBroadcastInfoState.Started,
+    );
+
+    // Set it as the current recording
+    VoiceBroadcastRecordingsStore.instance.setCurrent(recording);
+
+    return infoEvent;
+}

