+// stringToTracingPropagatorHookFunc returns a DecodeHookFunc that converts
+// strings or string slices to TracingPropagator or []TracingPropagator.
+func stringToTracingPropagatorHookFunc(mappings map[string]TracingPropagator) mapstructure.DecodeHookFunc {
+	return func(
+		f reflect.Type,
+		t reflect.Type,
+		data interface{}) (interface{}, error) {
+		// Handle string to TracingPropagator conversion
+		if f.Kind() == reflect.String && t == reflect.TypeOf(TracingPropagator("")) {
+			strData, ok := data.(string)
+			if !ok {
+				return data, nil
+			}
+			if val, ok := mappings[strData]; ok {
+				return val, nil
+			}
+			return data, nil
+		}
+
+		// Handle string slice to []TracingPropagator conversion
+		if f.Kind() == reflect.Slice && t == reflect.TypeOf([]TracingPropagator{}) {
+			rawSlice := reflect.ValueOf(data)
+			
+			// Check if the slice elements are already TracingPropagator
+			if rawSlice.Type().Elem() == reflect.TypeOf(TracingPropagator("")) {
+				return data, nil
+			}
+			
+			// Check if the slice elements are strings
+			if rawSlice.Type().Elem().Kind() != reflect.String {
+				// Data is already in the right format or can't be converted
+				return data, nil
+			}
+
+			result := make([]TracingPropagator, rawSlice.Len())
+			for i := 0; i < rawSlice.Len(); i++ {
+				strVal := rawSlice.Index(i).String()
+				if propagator, ok := mappings[strVal]; ok {
+					result[i] = propagator
+				} else {
+					result[i] = TracingPropagator(strVal)
+				}
+			}
+
+			return result, nil
+		}
+
+		return data, nil
+	}
+}
