+	var (
+		expectedFlag = &flipt.Flag{NamespaceKey: "ns", Key: "flag-1"}
+		store        = &common.StoreMock{}
+	)
+
+	store.On("GetFlag", context.TODO(), storage.NewResource("ns", "flag-1")).Return(
+		expectedFlag, nil,
+	)
+
+	unmodifiableStore := NewStore(store)
+
+	// Read operations should delegate to the underlying store
+	flag, err := unmodifiableStore.GetFlag(context.TODO(), storage.NewResource("ns", "flag-1"))
+	require.NoError(t, err)
+	assert.Equal(t, expectedFlag, flag)
+
+	store.AssertNumberOfCalls(t, "GetFlag", 1)
