+	"github.com/markphelps/flipt/rpc/flipt"
+	"github.com/markphelps/flipt/storage"
+	"gopkg.in/yaml.v2"
+)
+
+// Importer handles importing flags, variants, rules, distributions, and segments from a YAML document into the store.
+type Importer struct {
+	store storage.Store
+}
+
+// NewImporter creates a new Importer.
+func NewImporter(store storage.Store) *Importer {
+	return &Importer{
+		store: store,
+	}
+}
+
+// Import reads a YAML document from r, decodes it into a Document, and creates flags, variants, rules, distributions, segments, and constraints in the store.
+func (i *Importer) Import(ctx context.Context, r io.Reader) error {
+	dec := yaml.NewDecoder(r)
+	var doc Document
+
+	if err := dec.Decode(&doc); err != nil {
+		return fmt.Errorf("decoding YAML: %w", err)
+	}
+
+	// map flagKey => *flag
+	createdFlags := make(map[string]*flipt.Flag)
+	// map segmentKey => *segment
+	createdSegments := make(map[string]*flipt.Segment)
+	// map flagKey:variantKey => *variant
+	createdVariants := make(map[string]*flipt.Variant)
+
+	// create flags/variants
+	for _, f := range doc.Flags {
+		flag, err := i.store.CreateFlag(ctx, &flipt.CreateFlagRequest{
+			Key:         f.Key,
+			Name:        f.Name,
+			Description: f.Description,
+			Enabled:     f.Enabled,
+		})
+
+		if err != nil {
+			return fmt.Errorf("importing flag: %w", err)
+		}
+
+		for _, v := range f.Variants {
+			// Convert attachment from interface{} to JSON string
+			attachment := ""
+			if v.Attachment != nil {
+				// Use convert to ensure all map keys are strings
+				attachmentBytes, err := json.Marshal(convert(v.Attachment))
+				if err != nil {
+					return fmt.Errorf("marshaling attachment: %w", err)
+				}
+				attachment = string(attachmentBytes)
+			}
+
+			variant, err := i.store.CreateVariant(ctx, &flipt.CreateVariantRequest{
+				FlagKey:     f.Key,
+				Key:         v.Key,
+				Name:        v.Name,
+				Description: v.Description,
+				Attachment:  attachment,
+			})
+
+			if err != nil {
+				return fmt.Errorf("importing variant: %w", err)
+			}
+
+			createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
+		}
+
+		createdFlags[flag.Key] = flag
+	}
+
+	// create segments/constraints
+	for _, s := range doc.Segments {
+		segment, err := i.store.CreateSegment(ctx, &flipt.CreateSegmentRequest{
+			Key:         s.Key,
+			Name:        s.Name,
+			Description: s.Description,
+		})
+
+		if err != nil {
+			return fmt.Errorf("importing segment: %w", err)
+		}
+
+		for _, c := range s.Constraints {
+			_, err := i.store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
+				SegmentKey: s.Key,
+				Type:       flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
+				Property:   c.Property,
+				Operator:   c.Operator,
+				Value:      c.Value,
+			})
+
+			if err != nil {
+				return fmt.Errorf("importing constraint: %w", err)
+			}
+		}
+
+		createdSegments[segment.Key] = segment
+	}
+
+	// create rules/distributions
+	for _, f := range doc.Flags {
+		// loop through rules
+		for _, r := range f.Rules {
+			rule, err := i.store.CreateRule(ctx, &flipt.CreateRuleRequest{
+				FlagKey:    f.Key,
+				SegmentKey: r.SegmentKey,
+				Rank:       int32(r.Rank),
+			})
+
+			if err != nil {
+				return fmt.Errorf("importing rule: %w", err)
+			}
+
+			for _, d := range r.Distributions {
+				variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
+				if !found {
+					return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
+				}
+
+				_, err := i.store.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
+					FlagKey:   f.Key,
+					RuleId:    rule.Id,
+					VariantId: variant.Id,
+					Rollout:   d.Rollout,
+				})
+
+				if err != nil {
+					return fmt.Errorf("importing distribution: %w", err)
+				}
+			}
+		}
+	}
+
+	return nil
+}
+
+// convert normalizes all map keys to string types for JSON serialization compatibility.
+func convert(v interface{}) interface{} {
+	switch v := v.(type) {
+	case map[interface{}]interface{}:
+		// Convert map with interface{} keys to map[string]interface{}
+		m := make(map[string]interface{}, len(v))
+		for k, val := range v {
+			m[fmt.Sprintf("%v", k)] = convert(val)
+		}
+		return m
+	case map[string]interface{}:
+		// Recursively convert values in map
+		m := make(map[string]interface{}, len(v))
+		for k, val := range v {
+			m[k] = convert(val)
+		}
+		return m
+	case []interface{}:
+		// Recursively convert values in slice
+		s := make([]interface{}, len(v))
+		for i, val := range v {
+			s[i] = convert(val)
+		}
+		return s
+	default:
+		return v
+	}
+}

