+// parseListenPorts parses a listen port string and returns a ListenPort struct.
+// It supports formats like "127.0.0.1:22", "*:80", and "[::1]:443" (IPv6 with brackets).
+func (l *base) parseListenPorts(s string) models.ListenPort {
+	// For IPv6, find the last colon after the last bracket
+	// For IPv4 and wildcard, find the last colon
+	address := ""
+	port := ""
+	
+	// Check if it's IPv6 (contains brackets)
+	if strings.Contains(s, "[") {
+		// IPv6 format: [::1]:443 or [fe80::1]:8080
+		closeBracket := strings.LastIndex(s, "]")
+		if closeBracket > 0 {
+			address = s[:closeBracket+1] // include the closing bracket
+			if closeBracket+1 < len(s) && s[closeBracket+1] == ':' {
+				port = s[closeBracket+2:]
+			}
+		}
+	} else {
+		// IPv4 or wildcard format: 127.0.0.1:22 or *:80
+		lastColon := strings.LastIndex(s, ":")
+		if lastColon > 0 {
+			address = s[:lastColon]
+			port = s[lastColon+1:]
+		} else {
+			address = s
+		}
+	}
+	
+	// If port is empty, set it to empty string
+	if port == "" {
+		port = s
+	}
+	
+	return models.ListenPort{
+		Address:           address,
+		Port:              port,
+		PortScanSuccessOn: []string{},
+	}
+}
+
+// detectScanDest returns a deduplicated slice of "ip:port" strings for scanning.
+// For endpoints with address "*", it expands to all host IPv4 addresses.
+func (l *base) detectScanDest() []string {
+	dests := []string{}
+	
+	// Collect all scan destinations from packages
+	for _, pkg := range l.Packages {
+		for _, proc := range pkg.AffectedProcs {
+			for _, lp := range proc.ListenPorts {
+				if lp.Address == "*" {
+					// Expand wildcard to all IPv4 addresses
+					for _, ipv4 := range l.ServerInfo.IPv4Addrs {
+						dests = append(dests, ipv4+":"+lp.Port)
+					}
+				} else {
+					dests = append(dests, lp.Address+":"+lp.Port)
+				}
+			}
+		}
+	}
+	
+	// Deduplicate while preserving order (based on IPv4Addrs order for wildcard expansion)
+	seen := map[string]bool{}
+	uniqueDests := []string{}
+	for _, dest := range dests {
+		if !seen[dest] {
+			seen[dest] = true
+			uniqueDests = append(uniqueDests, dest)
+		}
+	}
+	
+	return uniqueDests
+}
+
+// updatePortStatus updates the PortScanSuccessOn field for all affected processes in the packages.
+func (l *base) updatePortStatus(listenIPPorts []string) {
+	// Create a map for quick lookup of successful scans
+	scanResults := map[string]bool{}
+	for _, dest := range listenIPPorts {
+		scanResults[dest] = true
+	}
+	
+	// Update all packages
+	for pkgName, pkg := range l.Packages {
+		for i, proc := range pkg.AffectedProcs {
+			for j, lp := range proc.ListenPorts {
+				var successIPs []string
+				if lp.Address == "*" {
+					// Check against all IPv4 addresses
+					for _, ipv4 := range l.ServerInfo.IPv4Addrs {
+						dest := ipv4 + ":" + lp.Port
+						if scanResults[dest] {
+							successIPs = append(successIPs, ipv4)
+						}
+					}
+				} else {
+					// Check exact address
+					dest := lp.Address + ":" + lp.Port
+					if scanResults[dest] {
+						successIPs = append(successIPs, lp.Address)
+					}
+				}
+				
+				// Deduplicate and sort for consistency
+				seen := map[string]bool{}
+				uniqueIPs := []string{}
+				for _, ip := range successIPs {
+					if !seen[ip] {
+						seen[ip] = true
+						uniqueIPs = append(uniqueIPs, ip)
+					}
+				}
+				// Sort for deterministic output
+				sort.Strings(uniqueIPs)
+				
+				proc.ListenPorts[j].PortScanSuccessOn = uniqueIPs
+			}
+			pkg.AffectedProcs[i] = proc
+		}
+		l.Packages[pkgName] = pkg
+	}
+}
+
+// findPortScanSuccessOn returns a non-nil slice of IPv4 addresses where the given listen port was confirmed open.
+func (l *base) findPortScanSuccessOn(listenIPPorts []string, searchListenPort models.ListenPort) []string {
+	result := []string{}
+	
+	// Check if the port is in the scan results
+	if searchListenPort.Address == "*" {
+		// Check against all IPv4 addresses
+		for _, ipv4 := range l.ServerInfo.IPv4Addrs {
+			dest := ipv4 + ":" + searchListenPort.Port
+			for _, scanned := range listenIPPorts {
+				if scanned == dest {
+					result = append(result, ipv4)
+					break
+				}
+			}
+		}
+	} else {
+		// Check exact address
+		dest := searchListenPort.Address + ":" + searchListenPort.Port
+		for _, scanned := range listenIPPorts {
+			if scanned == dest {
+				result = append(result, searchListenPort.Address)
+				break
+			}
+		}
+	}
+	
+	return result
+}
+
+// scanPorts attempts to connect to each ip:port and returns the list of successful ones.
+// It uses a short timeout suitable for a fast, low-noise check.
+func (l *base) scanPorts(dests []string) []string {
+	success := []string{}
+	timeout := 500 * time.Millisecond // Short timeout for fast scan
+	
+	for _, dest := range dests {
+		conn, err := net.DialTimeout("tcp", dest, timeout)
+		if err == nil {
+			conn.Close()
+			success = append(success, dest)
+		}
+	}
+	
+	return success
+}
