+func TestRemoveRaspbianPackFromResult_Raspbian(t *testing.T) {
+	r := ScanResult{
+		Family: constant.Raspbian,
+		Packages: Packages{
+			"pkg1":           {Name: "pkg1", Version: "1.0"},
+			"pkg2":           {Name: "pkg2", Version: "2.0"},
+			"libraspberrypi": {Name: "libraspberrypi", Version: "1.0"},
+			"rpi-eeprom":     {Name: "rpi-eeprom", Version: "1.0"},
+		},
+		SrcPackages: SrcPackages{
+			"src1":           {Name: "src1", Version: "1.0"},
+			"libraspberrypi": {Name: "libraspberrypi", Version: "1.0"},
+		},
+	}
+
+	result := r.RemoveRaspbianPackFromResult()
+
+	// For Raspbian, should return pointer to new object
+	if &r == result {
+		t.Errorf("For Raspbian, should return pointer to new object, not original")
+	}
+
+	// Raspbian packages should be filtered out
+	if len(result.Packages) != 2 {
+		t.Errorf("Expected 2 packages after filter, got %d", len(result.Packages))
+	}
+
+	if _, ok := result.Packages["libraspberrypi"]; ok {
+		t.Error("libraspberrypi should be filtered out")
+	}
+
+	if _, ok := result.Packages["rpi-eeprom"]; ok {
+		t.Error("rpi-eeprom should be filtered out")
+	}
+
+	// Check src packages
+	if len(result.SrcPackages) != 1 {
+		t.Errorf("Expected 1 src package after filter, got %d", len(result.SrcPackages))
+	}
+
+	if _, ok := result.SrcPackages["libraspberrypi"]; ok {
+		t.Error("libraspberrypi src package should be filtered out")
+	}
