+// RenameKernelSourcePackageName normalizes the kernel source package name according to the distribution family.
+// For Debian and Raspbian, it replaces "linux-signed" and "linux-latest" with "linux" and removes the suffixes "-amd64", "-arm64", and "-i386".
+// For Ubuntu, it replaces "linux-signed" and "linux-meta" with "linux".
+// If the family is unrecognized, it returns the original name unchanged.
+func RenameKernelSourcePackageName(family, name string) string {
+	switch family {
+	case constant.Debian, constant.Raspbian:
+		name = strings.ReplaceAll(name, "linux-signed", "linux")
+		name = strings.ReplaceAll(name, "linux-latest", "linux")
+		name = strings.ReplaceAll(name, "-amd64", "")
+		name = strings.ReplaceAll(name, "-arm64", "")
+		name = strings.ReplaceAll(name, "-i386", "")
+	case constant.Ubuntu:
+		name = strings.ReplaceAll(name, "linux-signed", "linux")
+		name = strings.ReplaceAll(name, "linux-meta", "linux")
+	}
+	return name
+}
+
+// IsKernelSourcePackage determines if a given package name is considered a kernel source package based on its name pattern and the distribution family.
+// Returns true for valid kernel source packages, false otherwise.
+func IsKernelSourcePackage(family, name string) bool {
+	switch family {
+	case constant.Debian, constant.Raspbian:
+		return isKernelSourcePackageDebian(name)
+	case constant.Ubuntu:
+		return isKernelSourcePackageUbuntu(name)
+	default:
+		// For unrecognized families, use a more permissive check
+		return isKernelSourcePackageGeneric(name)
+	}
+}
+
+func isKernelSourcePackageDebian(name string) bool {
+	switch ss := strings.Split(name, "-"); len(ss) {
+	case 1:
+		return name == "linux"
+	case 2:
+		if ss[0] != "linux" {
+			return false
+		}
+		switch ss[1] {
+		case "grsec":
+			return true
+		default:
+			_, err := strconv.ParseFloat(ss[1], 64)
+			return err == nil
+		}
+	default:
+		return false
+	}
+}
+
+func isKernelSourcePackageUbuntu(name string) bool {
+	switch ss := strings.Split(name, "-"); len(ss) {
+	case 1:
+		return name == "linux"
+	case 2:
+		if ss[0] != "linux" {
+			return false
+		}
+		switch ss[1] {
+		case "armadaxp", "mako", "manta", "flo", "goldfish", "joule", "raspi", "raspi2", "snapdragon", "aws", "azure", "bluefield", "dell300x", "gcp", "gke", "gkeop", "ibm", "lowlatency", "kvm", "oem", "oracle", "euclid", "hwe", "riscv":
+			return true
+		default:
+			_, err := strconv.ParseFloat(ss[1], 64)
+			return err == nil
+		}
+	case 3:
+		if ss[0] != "linux" {
+			return false
+		}
+		switch ss[1] {
+		case "ti":
+			return ss[2] == "omap4"
+		case "raspi", "raspi2", "gke", "gkeop", "ibm", "oracle", "riscv":
+			_, err := strconv.ParseFloat(ss[2], 64)
+			return err == nil
+		case "aws":
+			switch ss[2] {
+			case "hwe", "edge":
+				return true
+			default:
+				_, err := strconv.ParseFloat(ss[2], 64)
+				return err == nil
+			}
+		case "azure":
+			switch ss[2] {
+			case "fde", "edge":
+				return true
+			default:
+				_, err := strconv.ParseFloat(ss[2], 64)
+				return err == nil
+			}
+		case "gcp":
+			switch ss[2] {
+			case "edge":
+				return true
+			default:
+				_, err := strconv.ParseFloat(ss[2], 64)
+				return err == nil
+			}
+		case "intel":
+			switch ss[2] {
+			case "iotg":
+				return true
+			default:
+				_, err := strconv.ParseFloat(ss[2], 64)
+				return err == nil
+			}
+		case "oem":
+			switch ss[2] {
+			case "osp1":
+				return true
+			default:
+				_, err := strconv.ParseFloat(ss[2], 64)
+				return err == nil
+			}
+		case "lts":
+			return ss[2] == "xenial"
+		case "hwe":
+			switch ss[2] {
+			case "edge":
+				return true
+			default:
+				_, err := strconv.ParseFloat(ss[2], 64)
+				return err == nil
