+// parsePkgName parses a package name for a given package type and returns namespace, name, and subpath
+func parsePkgName(t, n string) (namespace, name, subpath string) {
+	switch t {
+	case "maven":
+		// Maven: split group:artifact into namespace and name
+		// e.g., "com.google.guava:guava" -> namespace="com.google.guava", name="guava"
+		idx := strings.Index(n, ":")
+		if idx != -1 {
+			return n[:idx], n[idx+1:], ""
+		}
+		return "", n, ""
+	case "pypi":
+		// PyPI: normalize by lowercasing and replacing underscores with hyphens
+		// e.g., "PyYAML" -> "pyyaml", "some_package" -> "some-package"
+		name = strings.ToLower(strings.ReplaceAll(n, "_", "-"))
+		return "", name, ""
+	case "golang":
+		// Golang: extract namespace and final segment of the path
+		// e.g., "github.com/protobom/protobom" -> namespace="github.com/protobom", name="protobom"
+		if idx := strings.LastIndex(n, "/"); idx != -1 {
+			return n[:idx], n[idx+1:], ""
+		}
+		return "", n, ""
+	case "npm":
+		// npm: split scoped package names into namespace and name
+		// e.g., "@babel/core" -> namespace="@babel", name="core"
+		if strings.HasPrefix(n, "@") {
+			if idx := strings.Index(n, "/"); idx != -1 {
+				return n[:idx], n[idx+1:], ""
+			}
+		}
+		return "", n, ""
+	case "cocoapods":
+		// Cocoapods: separate main name and subpath
+		// e.g., "GoogleUtilities/NSData+zlib" -> name="GoogleUtilities", subpath="NSData+zlib"
+		if idx := strings.Index(n, "/"); idx != -1 {
+			return "", n[:idx], n[idx+1:]
+		}
+		return "", n, ""
+	default:
+		// For unknown types, return empty namespace and subpath, use full name
+		return "", n, ""
+	}
+}

