+func (t *Table) truncateCell(colIndex int, cell string) string {
+	if colIndex >= len(t.columns) {
+		return cell
+	}
+
+	col := t.columns[colIndex]
+	if col.MaxCellLength > 0 && len(cell) > col.MaxCellLength {
+		truncated := cell[:col.MaxCellLength]
+		if col.FootnoteLabel != "" {
+			return truncated + fmt.Sprintf("[%s]", col.FootnoteLabel)
+		}
+		return truncated
+	}
+	return cell
+}
+
+// needsTruncation checks if a cell needs truncation based on the column's MaxCellLength.
+func (t *Table) needsTruncation(colIndex int, cell string) bool {
+	if colIndex >= len(t.columns) {
+		return false
+	}
+
+	col := t.columns[colIndex]
+	return col.MaxCellLength > 0 && len(cell) > col.MaxCellLength
+}
