+// checkSignatureAndEntitlements checks if the binary has a valid signature and entitlements.
+void checkSignatureAndEntitlements(BOOL *outHasSignature, BOOL *outHasEntitlements, char **outErr) {
+  if (!outHasSignature || !outHasEntitlements || !outErr) {
+    return;
+  }
+  
+  *outHasSignature = NO;
+  *outHasEntitlements = NO;
+  *outErr = NULL;
+  
+  @autoreleasepool {
+    // Check code signature
+    CFErrorRef error = NULL;
+    SecStaticCodeRef staticCode = NULL;
+    OSStatus status = SecStaticCodeCreateWithPath((CFURLRef)[[NSBundle mainBundle] bundleURL], kSecCSDefaultFlags, &staticCode);
+    
+    if (status == errSecSuccess && staticCode) {
+      *outHasSignature = YES;
+      
+      // Check entitlements
+      CFDictionaryRef entitlements = NULL;
+      status = SecCodeCopyStaticInformation(staticCode, kSecCodeInfoEntitlementsDictionary, &entitlements);
+      
+      if (status == errSecSuccess && entitlements) {
+        // Check for the touchid entitlement
+        NSDictionary *entitlementsDict = (NSDictionary *)entitlements;
+        id touchIDEntitlement = [entitlementsDict objectForKey:@"com.apple.developer.team-identifier"];
+        if (touchIDEntitlement) {
+          *outHasEntitlements = YES;
+        }
+        CFRelease(entitlements);
+      }
+      
+      CFRelease(staticCode);
+    } else if (error) {
+      NSString *errString = CFBridgingRelease(CFErrorCopyDescription(error));
+      *outErr = strdup([errString UTF8String]);
+      CFRelease(error);
+    }
+  }
+}
+
+// checkLAPolicy performs a LocalAuthentication policy test.
+void checkLAPolicy(BOOL *outPassed, char **outErr) {
+  if (!outPassed || !outErr) {
+    return;
+  }
+  
+  *outPassed = NO;
+  *outErr = NULL;
+  
+  @autoreleasepool {
+    LAContext *context = [[LAContext alloc] init];
+    context.localizedFallbackTitle = @"Enter Password";
+    
+    NSError *error = nil;
+    BOOL canEvaluate = [context canEvaluatePolicy:LAPolicyDeviceOwnerAuthenticationWithBiometrics
+                                          error:&error];
+    
+    if (canEvaluate) {
+      *outPassed = YES;
+    } else if (error) {
+      *outErr = strdup([error.localizedDescription UTF8String]);
+    }
+  }
+}
+
+// checkSecureEnclave performs a Secure Enclave test.
+void checkSecureEnclave(BOOL *outPassed, char **outErr) {
+  if (!outPassed || !outErr) {
+    return;
+  }
+  
+  *outPassed = NO;
+  *outErr = NULL;
+  
+  @autoreleasepool {
+    // Try to generate a key pair using the Secure Enclave
+    NSDictionary *parameters = @{
+      (__bridge id)kSecAttrKeySizeInBits: @256,
+      (__bridge id)kSecAttrTokenID: kSecAttrTokenIDSecureEnclave,
+      (__bridge id)kSecPrivateKeyAttrs: @{
+        (__bridge id)kSecAttrIsPermanent: @NO,
+        (__bridge id)kSecAttrAccessControl: (__bridge id)SecAccessControlCreateWithFlags(
+          NULL,
+          kSecAccessControlUserPresence,
+          kSecAccessControlCreateFlagsUsePasscode,
+          NULL
+        )
+      }
+    };
+    
+    CFErrorRef error = NULL;
+    CFTypeRef privateKey = NULL;
+    CFTypeRef publicKey = NULL;
+    
+    OSStatus status = SecKeyGeneratePair((__bridge CFDictionaryRef)parameters, &publicKey, &privateKey);
+    
+    if (status == errSecSuccess) {
+      *outPassed = YES;
+      
+      // Clean up
+      if (publicKey) {
+        CFRelease(publicKey);
+      }
+      if (privateKey) {
+        CFRelease(privateKey);
+      }
+    } else if (error) {
+      NSString *errString = CFBridgingRelease(CFErrorCopyDescription(error));
+      *outErr = strdup([errString UTF8String]);
+    }
+  }
+}
