+// MakeTableWithTruncatedColumn builds a table that adapts widths to terminal
+// size and truncates the designated column to keep readability.
+// The truncatedColumn parameter specifies which column should be truncated.
+// If truncatedColumn doesn't match any real header, all columns will have
+// their natural widths without truncation.
+func MakeTableWithTruncatedColumn(columnOrder []string, rows [][]string, truncatedColumn string) Table {
+	width, _, err := getTerminalSize()
+	if err != nil {
+		width = 80
+	}
+
+	truncatedColMinSize := 16
+	t := MakeTable([]string{})
+	totalLen := 0
+	columns := []Column{}
+	truncatedColumnFound := false
+
+	// First pass: identify columns and calculate widths
+	for collIndex, colName := range columnOrder {
+		column := Column{
+			Title:         colName,
+			MaxCellLength: len(colName),
+		}
+
+		if colName == truncatedColumn {
+			// Store the truncated column to be processed later
+			columns = append(columns, column)
+			truncatedColumnFound = true
+			continue
+		}
+
+		// Find the maximum cell length for this column
+		for _, row := range rows {
+			if collIndex < len(row) {
+				cellLen := row[collIndex]
+				if len(cellLen) > column.MaxCellLength {
+					column.MaxCellLength = len(cellLen)
+				}
+			}
+		}
+
+		columns = append(columns, column)
+	}
+
+	// If the truncated column was found, apply width constraints
+	if truncatedColumnFound {
+		// Calculate maxColWidth based on terminal width, leaving space for the truncated column
+		// We subtract 1 from the number of columns to calculate max width for non-truncated columns
+		maxColWidth := (width - truncatedColMinSize) / (len(columnOrder) - 1)
+		if maxColWidth < 10 {
+			maxColWidth = 10
+		}
+
+		// Calculate total length for non-truncated columns
+		for _, column := range columns {
+			if column.Title == truncatedColumn {
+				continue
+			}
+			if column.MaxCellLength > maxColWidth {
+				column.MaxCellLength = maxColWidth
+				totalLen += column.MaxCellLength + 4 // "...<space>"
+			} else {
+				totalLen += column.MaxCellLength + 1 // +1 for column separator
+			}
+		}
+
+		// Process the truncated column with remaining width
+		for i := range columns {
+			if columns[i].Title == truncatedColumn {
+				columns[i].MaxCellLength = width - totalLen - len("... ")
+				// Ensure minimum width for the truncated column
+				if columns[i].MaxCellLength < 16 {
+					columns[i].MaxCellLength = 16
+				}
+				break
+			}
+		}
+	}
+
+	// Add all columns to the table
+	for _, column := range columns {
+		t.AddColumn(column)
+	}
+
+	// Add all rows
+	for _, row := range rows {
+		t.AddRow(row)
+	}
+
+	return t
+}
+
+// getTerminalSize returns the terminal size (width, height) from stdin.
+// It returns an error if the terminal size cannot be determined.
