+// TestTeleportProxy tests that connections with Teleport-Proxy prefix
+// are correctly detected as SSH connections and the ClientAddr is extracted.
+func TestTeleportProxy(t *testing.T) {
+	t.Parallel()
+
+	// Create a simple SSH handler that checks the remote address
+	var gotRemoteAddr string
+	var channelOpened = make(chan bool, 1)
+	sshHandler := sshutils.NewChanHandlerFunc(func(_ context.Context, connCtx *sshutils.ConnectionContext, nch ssh.NewChannel) {
+		// The SSH server wraps the connection with a connectionWrapper
+		// that overrides RemoteAddr(). We need to access the underlying
+		// connection to get the remote address.
+		gotRemoteAddr = connCtx.NetConn.RemoteAddr().String()
+		t.Logf("SSH handler called, remote address: %v", gotRemoteAddr)
+		err := nch.Reject(ssh.Prohibited, "nothing to see here")
+		require.Nil(t, err)
+		channelOpened <- true
+	})
+
+	_, signer, err := utils.CreateCertificate("foo", ssh.HostCert)
+	require.Nil(t, err)
+
+	srv, err := sshutils.NewServer(
+		"test",
+		utils.NetAddr{AddrNetwork: "tcp", Addr: "localhost:0"},
+		sshHandler,
+		[]ssh.Signer{signer},
+		sshutils.AuthMethods{Password: pass("abc123")},
+	)
+	require.Nil(t, err)
+
+	listener, err := net.Listen("tcp", "127.0.0.1:0")
+	require.Nil(t, err)
+
+	mux, err := New(Config{
+		Listener: listener,
+	})
+	require.Nil(t, err)
+	go mux.Serve()
+	defer mux.Close()
+
+	// Serve SSH on the multiplexer
+	go srv.Serve(mux.SSH())
+	defer srv.Close()
+
+	// Import the HandshakePayload and ProxyHelloSignature from the api package
+	hp := &apisshutils.HandshakePayload{
+		ClientAddr: "192.168.1.100:54321",
+	}
+	payloadJSON, err := json.Marshal(hp)
+	require.Nil(t, err)
+
+	// Write the Teleport-Proxy message (without SSH version string)
+	// The SSH client will write its own version string during handshake
+	payload := fmt.Sprintf("%s%s\x00", apisshutils.ProxyHelloSignature, payloadJSON)
