+// MaskKeyName masks the key name by replacing the first 75% of its bytes with '*'.
+// It returns the masked key name as a byte slice, preserving the original length.
+func MaskKeyName(keyName string) []byte {
+	if len(keyName) == 0 {
+		return []byte{}
+	}
+	
+	hiddenBefore := int(math.Floor(0.75 * float64(len(keyName))))
+	asterisks := bytes.Repeat([]byte("*"), hiddenBefore)
+	masked := append(asterisks, keyName[hiddenBefore:]...)
+	return masked
+}
