+		cfg.BufferSize = 1024
+	}
+	if cfg.BackoffTimeout == 0 {
+		cfg.BackoffTimeout = 5 * time.Second
+	}
+	if cfg.BackoffDuration == 0 {
+		cfg.BackoffDuration = 5 * time.Second
+	}
+	return nil
+}
+
+// AsyncEmitter is an emitter that enqueues events and forwards them in the background
+// It drops events on overflow and provides non-blocking emission
+type AsyncEmitter struct {
+	cfg      AsyncEmitterConfig
+	eventsCh chan AuditEvent
+	done     chan struct{}
+	stats    *AsyncEmitterStats
+	ctx      context.Context
+	cancel   context.CancelFunc
+}
+
+// AsyncEmitterStats contains counters for async emitter statistics
+type AsyncEmitterStats struct {
+	// AcceptedEvents is the number of events accepted by the emitter
+	AcceptedEvents int64
+	// LostEvents is the number of events lost due to buffer overflow
+	LostEvents int64
+	// SlowWrites is the number of slow writes that required backoff
+	SlowWrites int64
+}
+
+// NewAsyncEmitter creates a non-blocking async emitter
+func NewAsyncEmitter(cfg AsyncEmitterConfig) (*AsyncEmitter, error) {
+	if err := cfg.CheckAndSetDefaults(); err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	ctx, cancel := context.WithCancel(context.Background())
+	emitter := &AsyncEmitter{
+		cfg:      cfg,
+		eventsCh: make(chan AuditEvent, cfg.BufferSize),
+		done:     make(chan struct{}),
+		stats: &AsyncEmitterStats{},
+		ctx:      ctx,
+		cancel:   cancel,
+	}
+	go emitter.processEvents()
+	return emitter, nil
+}
+
+// EmitAuditEvent emits audit event asynchronously (non-blocking)
+// It enqueues the event to the buffer and drops/logs on overflow
+func (e *AsyncEmitter) EmitAuditEvent(ctx context.Context, event AuditEvent) error {
+	select {
+	case e.eventsCh <- event:
+		e.stats.AcceptedEvents++
+		return nil
+	default:
+		// Buffer is full, drop the event
+		e.stats.LostEvents++
+		log.Debugf("Async emitter buffer full, dropping event")
+		return trace.LimitExceeded("async emitter buffer is full")
+	}
+}
+
+// Close cancels background processing and prevents further submissions
+func (e *AsyncEmitter) Close() error {
+	e.cancel()
+	// Wait for background processing to complete
+	<-e.done
+	return nil
+}
+
+// Stats returns a snapshot of the async emitter counters
+func (e *AsyncEmitter) Stats() AsyncEmitterStats {
+	return AsyncEmitterStats{
+		AcceptedEvents: e.stats.AcceptedEvents,
+		LostEvents:     e.stats.LostEvents,
+		SlowWrites:     e.stats.SlowWrites,
+	}
+}
+
+// processEvents processes events from the buffer in the background
+func (e *AsyncEmitter) processEvents() {
+	defer close(e.done)
+
+	for {
+		select {
+		case <-e.ctx.Done():
+			return
+		case event := <-e.eventsCh:
+			err := e.cfg.Inner.EmitAuditEvent(e.ctx, event)
+			if err != nil {
+				e.stats.SlowWrites++
+				log.WithError(err).Debug("Failed to emit event, will retry with backoff")
+				// Implement backoff logic here
+				e.cfg.Clock.Sleep(e.cfg.BackoffDuration)
+				// Try again with timeout
+				timeoutCtx, timeoutCancel := context.WithTimeout(e.ctx, e.cfg.BackoffTimeout)
+				select {
+				case e.eventsCh <- event:
+					// Re-queued successfully
+					timeoutCancel()
+					continue
+				case <-timeoutCtx.Done():
+					// Timed out, drop the event
+					timeoutCancel()
+					e.stats.LostEvents++
+					log.WithError(err).Debug("Failed to emit event after backoff, dropping")
+				case <-e.ctx.Done():
+					// Emitter closed
+					return
+				}
+			}
+		}
+	}
+}

