+package utils
+
+import (
+	"sync"
+
+	"github.com/gravitational/trace"
+)
+
+// CircularBuffer is a concurrency-safe, fixed-capacity circular buffer for float64 values.
+type CircularBuffer struct {
+	mu     sync.Mutex
+	data   []float64
+	start  int
+	end    int
+	size   int
+	cap    int
+}
+
+// NewCircularBuffer creates a circular buffer with the given size and validates it is positive.
+func NewCircularBuffer(size int) (*CircularBuffer, error) {
+	if size <= 0 {
+		return nil, trace.BadParameter("circular buffer size must be greater than zero")
+	}
+	return &CircularBuffer{
+		data:  make([]float64, size),
+		start: -1,
+		end:   -1,
+		size:  0,
+		cap:   size,
+	}, nil
+}
+
+// Add appends a value while maintaining maximum capacity.
+func (c *CircularBuffer) Add(d float64) {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+
+	if c.size == 0 {
+		c.start = 0
+		c.end = 0
+		c.size = 1
+		c.data[c.end] = d
+		return
+	}
+
+	if c.size < c.cap {
+		c.end = (c.end + 1) % c.cap
+		c.data[c.end] = d
+		c.size++
+	} else {
+		c.end = c.start
+		c.start = (c.start + 1) % c.cap
+		c.data[c.end] = d
+	}
+}
+
+// Data returns up to n most recent values in insertion order.
+func (c *CircularBuffer) Data(n int) []float64 {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+
+	if n <= 0 || c.size == 0 {
+		return nil
+	}
+
+	// Limit n to the actual size
+	if n > c.size {
+		n = c.size
+	}
+
+	out := make([]float64, n)
+	for i := 0; i < n; i++ {
+		index := (c.start + i) % c.cap
+		out[i] = c.data[index]
+	}
+	return out
+}
