+// getReverseProxyUser checks if the request is from a trusted reverse proxy
+// and returns the username from the configured header if available.
+// The second return value is true if reverse proxy authentication should be attempted.
+func getReverseProxyUser(r *http.Request) (string, bool) {
+	if conf.Server.ReverseProxyWhitelist == "" && !strings.HasPrefix(conf.Server.Address, "unix:") {
+		return "", false
+	}
+	
+	reverseProxyIp, ok := request.ReverseProxyIpFrom(r.Context())
+	if !ok {
+		// Reverse proxy IP not set in context, try to get it from RemoteAddr
+		reverseProxyIp = r.RemoteAddr
+	}
+	
+	if !validateIPAgainstList(reverseProxyIp, conf.Server.ReverseProxyWhitelist) {
+		return "", false
+	}
+	
+	username := r.Header.Get(conf.Server.ReverseProxyUserHeader)
+	if username == "" {
+		return "", false
+	}
+	
+	log.Trace(r, "Found username in ReverseProxyUserHeader", "username", username)
+	return username, true
+}
+
+// validateIPAgainstList checks if the given IP is in the whitelist CIDR list.
+// It's a copy of the server.validateIPAgainstList function to avoid import cycles.
+func validateIPAgainstList(ip string, commaSeparatedList string) bool {
+	// Per https://github.com/golang/go/issues/49825, the remote address
+	// on a unix socket is '@'
+	if ip == "@" && strings.HasPrefix(conf.Server.Address, "unix:") {
+		return true
+	}
+
+	if commaSeparatedList == "" || ip == "" {
+		return false
+	}
+
+	if net.ParseIP(ip) == nil {
+		ip, _, _ = net.SplitHostPort(ip)
+	}
+
+	if ip == "" {
+		return false
+	}
+
+	cidrs := strings.Split(commaSeparatedList, ",")
+	testedIP, _, err := net.ParseCIDR(fmt.Sprintf("%s/32", ip))
+
+	if err != nil {
+		return false
+	}
+
+	for _, cidr := range cidrs {
+		_, ipnet, err := net.ParseCIDR(cidr)
+		if err == nil && ipnet.Contains(testedIP) {
+			return true
+		}
+	}
+
+	return false
+}
+
+// validateCredentials validates Subsonic credentials (plaintext, encoded, token+salt, or JWT)
+// and returns model.ErrInvalidAuth when validation fails.
+func validateCredentials(ctx context.Context, user *model.User, pass, token, salt, jwt string) error {
+	// Check JWT first
+	if jwt != "" {
+		claims, err := auth.Validate(jwt)
+		if err != nil || claims["sub"] != user.UserName {
+			return model.ErrInvalidAuth
+		}
+		return nil
+	}
+	
+	// Check plaintext or encoded password
+	if pass != "" {
+		if strings.HasPrefix(pass, "enc:") {
+			if dec, err := hex.DecodeString(pass[4:]); err == nil {
+				pass = string(dec)
+			}
+		}
+		if pass == user.Password {
+			return nil
+		}
+		return model.ErrInvalidAuth
+	}
+	
+	// Check token+salt
+	if token != "" {
+		if salt == "" {
+			return model.ErrInvalidAuth
+		}
+		t := fmt.Sprintf("%x", md5.Sum([]byte(user.Password+salt)))
+		if t == token {
+			return nil
+		}
+		return model.ErrInvalidAuth
+	}
+	
+	// No credentials provided
+	return model.ErrInvalidAuth
+}

