+// ToM3U8 generates an Extended M3U8 format string from the playlist data
+func (pls Playlist) ToM3U8() string {
+	var lines []string
+	lines = append(lines, "#EXTM3U")
+	if pls.Name != "" {
+		lines = append(lines, "#PLAYLIST:"+pls.Name)
+	}
+	for _, track := range pls.Tracks {
+		duration := int(track.Duration + 0.5) // Round to nearest second
+		line := "#EXTINF:" + strconv.Itoa(duration) + "," + track.Artist + " - " + track.Title
+		lines = append(lines, line)
+		lines = append(lines, track.Path)
+	}
+	return strings.Join(lines, "\n")
+}
