+)
+
+// All is an alias of squirrel.And for logical conjunctions
+type All squirrel.And
+
+// ToSql generates SQL with AND between conditions
+func (a All) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.And(a).ToSql()
+}
+
+// Any is an alias of squirrel.Or for logical disjunctions
+type Any squirrel.Or
+
+// ToSql generates SQL with OR between conditions
+func (o Any) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Or(o).ToSql()
+}
+
+// Is exact equality operator
+type Is struct {
+	Field string
+	Value interface{}
+}
+
+// ToSql generates equality SQL with placeholders using fieldMap
+func (i Is) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Eq{i.Field: i.Value}.ToSql()
+}
+
+// IsNot inequality operator
+type IsNot struct {
+	Field string
+	Value interface{}
+}
+
+// ToSql generates inequality SQL with placeholders using fieldMap
+func (n IsNot) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.NotEq{n.Field: n.Value}.ToSql()
+}
+
+// Contains text search operator with %value% pattern
+type Contains struct {
+	Field string
+	Value interface{}
+}
