+// DecodeArtworkID validates and decodes a JWT token string, extracting the artwork ID.
+// Returns an error if the token is invalid, missing the "id" claim, or the ID is empty.
+func DecodeArtworkID(tokenString string) (model.ArtworkID, error) {
+	claims, err := auth.Validate(tokenString)
+	if err != nil {
+		return model.ArtworkID{}, errors.New("invalid JWT")
+	}
+
+	id, ok := claims["id"].(string)
+	if !ok {
+		return model.ArtworkID{}, errors.New("invalid JWT")
+	}
+
+	artID, err := model.ParseArtworkID(id)
+	if err != nil {
+		return model.ArtworkID{}, errors.New("invalid artwork id")
+	}
+
+	if artID.ID == "" {
+		return model.ArtworkID{}, errors.New("invalid artwork id")
+	}
+
+	return artID, nil
+}
+
+// PublicLink generates a public URL for an artwork with the given size.
+// The size is passed as a query parameter instead of being embedded in the token.
+func PublicLink(artID model.ArtworkID, size int) string {
+	token := EncodeArtworkID(artID)
+	if size > 0 {
+		return token + "?size=" + string(rune(size))
+	}
+	return token
+}
