+// validateIPAgainstList checks if an IP address matches any CIDR in the whitelist
+func validateIPAgainstList(ipStr string, whitelist string) bool {
+	if whitelist == "" {
+		return false
+	}
+
+	// Handle Unix socket
+	if ipStr == "@" {
+		return strings.Contains(whitelist, "@")
+	}
+
+	// Parse the IP
+	ip := net.ParseIP(ipStr)
+	if ip == nil {
+		return false
+	}
+
+	// Split the whitelist by comma
+	ranges := strings.Split(whitelist, ",")
+	for _, rangeStr := range ranges {
+		rangeStr = strings.TrimSpace(rangeStr)
+		if rangeStr == "" {
+			continue
+		}
+
+		// Handle IP:port format
+		host, _, err := net.SplitHostPort(rangeStr)
+		if err != nil {
+			// Not IP:port format, try as CIDR directly
+			host = rangeStr
+		}
+
+		// Parse CIDR
+		_, cidr, err := net.ParseCIDR(host)
+		if err != nil {
+			// Not a valid CIDR, skip
+			continue
+		}
+
+		// Check if IP is in CIDR
+		if cidr.Contains(ip) {
+			return true
+		}
+	}
+
+	return false
+}
+
+// HandleLoginFromHeaders attempts to authenticate a user based on HTTP headers
+// Returns the user if authentication is successful, nil otherwise
+func HandleLoginFromHeaders(ds model.DataStore, r *http.Request) (*model.User, error) {
+	ctx := r.Context()
+	return handleLoginFromHeaders(ctx, ds, r)
+}
+
+// handleLoginFromHeaders attempts to authenticate a user based on HTTP headers
+// Returns the user if authentication is successful, nil otherwise
+func handleLoginFromHeaders(ctx context.Context, ds model.DataStore, r *http.Request) (*model.User, error) {
+	// Check if reverse proxy authentication is enabled
+	if conf.Server.ReverseProxyWhitelist == "" {
+		return nil, nil
+	}
+
+	// Get the client IP
+	clientIP, _, err := net.SplitHostPort(r.RemoteAddr)
+	if err != nil {
+		// If RemoteAddr doesn't have a port, use it directly
+		clientIP = r.RemoteAddr
+	}
+
+	// Check if the client IP is in the whitelist
+	if !validateIPAgainstList(clientIP, conf.Server.ReverseProxyWhitelist) {
+		return nil, nil
+	}
+
+	// Get the username from the configured header
+	headerName := conf.Server.ReverseProxyUserHeader
+	if headerName == "" {
+		headerName = "Remote-User"
+	}
+	username := r.Header.Get(headerName)
+	if username == "" {
+		return nil, nil
+	}
+
+	// Find or create the user
+	user, err := ds.User(ctx).FindByUsername(username)
+	if err == model.ErrNotFound {
+		// Create user on first login via reverse proxy
+		// The first user created is set as admin
+		count, err := ds.User(ctx).CountAll()
+		if err != nil {
+			log.Error(ctx, "Could not count users", err)
+			return nil, err
+		}
+
+		log.Info(ctx, "Creating user from reverse proxy authentication", "username", username, "admin", count == 0)
+		now := time.Now()
+		user = &model.User{
+			ID:          uuid.NewString(),
+			UserName:    username,
+			Name:        strings.Title(username),
+			Email:       "",
+			NewPassword: "", // No password for reverse proxy auth
+			IsAdmin:     count == 0, // First user is admin
+			LastLoginAt: &now,
+		}
+		err = ds.User(ctx).Put(user)
+		if err != nil {
+			log.Error(ctx, "Could not create user from reverse proxy", "username", username, err)
+			return nil, err
+		}
+	} else if err != nil {
+		log.Error(ctx, "Error finding user from reverse proxy", "username", username, err)
+		return nil, err
+	}
+
+	// Update last login time
+	err = ds.User(ctx).UpdateLastLoginAt(user.ID)
+	if err != nil {
+		log.Error(ctx, "Could not update LastLoginAt", "user", user.UserName, err)
+	}
+
+	return user, nil
+}
