+// redactValue redacts a single value based on the redaction regex
+// It handles different types: string, map, and other types (via stringification)
+func redactValue(re *regexp.Regexp, v interface{}) interface{} {
+	switch val := v.(type) {
+	case string:
+		// For strings, apply the regex replacement
+		return re.ReplaceAllString(val, "$1[REDACTED]$2")
+	case map[string]interface{}:
+		// For maps, recursively redact each value while preserving keys
+		redactedMap := make(map[string]interface{})
+		for k, v := range val {
+			redactedMap[k] = redactValue(re, v)
+		}
+		return redactedMap
+	default:
+		// For other types, stringify and apply regex
+		str := fmt.Sprintf("%v", val)
+		redacted := re.ReplaceAllString(str, "$1[REDACTED]$2")
+		// Try to parse the redacted string back to the original type if possible
+		// Otherwise, return the redacted string
+		return redacted
+	}
+}
