+// Any is a wildcard constant for refresh events
+const Any = "*"
+
 type RefreshResource struct {
 	baseEvent
-	Resource string `json:"resource"`
+	resources map[string][]string
+}
+
+// NewRefreshResource creates a new RefreshResource event
+func NewRefreshResource() *RefreshResource {
+	return &RefreshResource{
+		resources: make(map[string][]string),
+	}
+}
+
+// With accumulates resources and their IDs, allowing method chaining
+func (rr *RefreshResource) With(resource string, ids ...string) *RefreshResource {
+	if rr.resources == nil {
+		rr.resources = make(map[string][]string)
+	}
+	// Filter out Any wildcards from the input and add them if needed
+	hasAny := false
+	filteredIds := make([]string, 0, len(ids))
+	for _, id := range ids {
+		if id == Any {
+			hasAny = true
+		} else {
+			filteredIds = append(filteredIds, id)
+		}
+	}
+	// If Any is present, replace with just Any
+	if hasAny {
+		filteredIds = []string{Any}
+	}
+	// Accumulate IDs for this resource
+	existingIds := rr.resources[resource]
+	rr.resources[resource] = append(existingIds, filteredIds...)
+	return rr
+}
+
+// Data serializes the event to JSON
+func (rr *RefreshResource) Data(evt Event) string {
+	// If no resources are specified, send full refresh signal
+	if len(rr.resources) == 0 {
+		return `{"*":"*"}`
+	}
+	
+	data, _ := json.Marshal(rr.resources)
+	return string(data)
 }

