+
+export const getMinExpirationTime = (date: Date) => {
+    // If date is not today, there is no min time because we want to display all intervals
+    if (!isToday(date)) {
+        return undefined;
+    }
+
+    // Current time
+    const now = new Date();
+    
+    // Round down to the nearest 30-minute boundary
+    const nowRounded = new Date(now);
+    nowRounded.setMinutes(Math.floor(nowRounded.getMinutes() / 30) * 30, 0, 0);
+    
+    // Calculate the next 30-minute intervals
+    const nextIntervals = Array.from(Array(3)).map((_, i) => {
+        const interval = new Date(nowRounded);
+        return addMinutes(interval, 30 * (i + 1));
+    });
+    
+    // Check which interval is at least 30 minutes ahead
+    // We need to find the first interval where (interval - now) >= 30 minutes
+    for (const interval of nextIntervals) {
+        const diffInMinutes = (interval.getTime() - now.getTime()) / (1000 * 60);
+        if (diffInMinutes >= 30) {
+            return interval;
+        }
+    }
+    
+    // Fallback to the first interval (shouldn't happen in practice)
+    return nextIntervals[0];
+};

