+import { useMemo } from 'react';
+
+import { Recipient } from '@proton/shared/lib/interfaces/Address';
+
+import { isProtonRecipient } from '../../helpers/elements';
+import { getSenders as getConversationSenders } from '../../helpers/conversation';
+import { getSender } from '@proton/shared/lib/mail/messages';
+import { isMessage } from '../../helpers/elements';
+import ProtonBadge from './ProtonBadge';
+
+interface Props {
+    element: any;
+    conversationMode: boolean;
+    loading: boolean;
+    unread: boolean;
+    displayRecipients: boolean;
+    isSelected: boolean;
+}
+
+const ItemSenders = ({ element, conversationMode, loading, unread, displayRecipients, isSelected }: Props) => {
+    // Get senders or recipients based on displayRecipients
+    const senders = useMemo(() => {
+        if (displayRecipients) {
+            // Get recipients
+            if (isMessage(element)) {
+                // For messages, we would get recipients from the message
+                // But we'll return an empty array for now
+                return [];
+            }
+            // For conversations, get recipients from the conversation
+            const conversation = element;
+            return conversation.Recipients || [];
+        }
+
+        // Get senders
+        if (conversationMode) {
+            return getConversationSenders(element);
+        }
+
+        const sender = getSender(element);
+        if (sender) {
+            return [sender];
+        }
+
+        return [];
+    }, [element, conversationMode, displayRecipients]);
+
+    // Check if any sender is from Proton
+    const hasProtonSender = useMemo(() => {
+        if (loading) {
+            return false;
+        }
+
+        // Check if the element itself is from Proton
+        if (element.IsProton) {
+            return true;
+        }
+
+        // Check if any sender is from Proton
+        return senders.some((sender: Recipient) => {
+            return isProtonRecipient(element, sender, displayRecipients);
+        });
+    }, [element, senders, displayRecipients, loading]);
+
+    // Get sender names for display
+    const senderNames = useMemo(() => {
+        return senders.map((sender: Recipient) => sender?.Name || sender?.Address || '').join(', ');
+    }, [senders]);
+
+    // Get sender addresses for display
+    const senderAddresses = useMemo(() => {
+        return senders.map((sender: Recipient) => sender?.Address || '').join(', ');
+    }, [senders]);
+
+    return (
+        <div className="flex flex-align-items-center flex-nowrap">
+            <span className="max-w100 text-ellipsis" title={senderAddresses} data-testid="message-senders">
+                {senderNames}
+            </span>
+            {hasProtonSender && !displayRecipients && (
+                <ProtonBadge selected={isSelected} />
+            )}
+        </div>
+    );
+};
+
+export default ItemSenders;
