+import { isMessage } from './elements';
+
+/**
+ * Get senders/recipient information from an element for display in mail lists
+ * @param element The element (message or conversation)
+ * @param conversationMode Whether we're in conversation mode
+ * @param displayRecipients Whether to display recipients instead of senders
+ * @returns Array of recipients
+ */
+export const getElementSenders = (
+    element: Element,
+    conversationMode: boolean,
+    displayRecipients: boolean
+): Recipient[] => {
+    if (displayRecipients) {
+        // Get recipients instead of senders
+        if (isMessage(element)) {
+            // For messages, we would get recipients from the message
+            // But we'll return an empty array for now
+            return [];
+        }
+        // For conversations, get recipients from the conversation
+        const conversation = element as Conversation;
+        return conversation.Recipients || [];
+    }
+
+    // Get senders
+    if (conversationMode) {
+        const conversation = element as Conversation;
+        return conversation.Senders || [];
+    }
+
+    // For messages, get the sender
+    if (isMessage(element)) {
+        // Note: We need to import getSender from @proton/shared/lib/mail/messages
+        // But we can't do that here to avoid circular dependencies
+        // So we'll return an empty array for now
+        return [];
+    }
+
+    return [];
+};
+
+/**
+ * Check if a specific sender/recipient is from Proton
+ * @param element The element (message or conversation)
+ * @param recipient The recipient to check
+ * @param displayRecipients Whether to display recipients instead of senders
+ * @returns true if the sender/recipient is from Proton
+ */
+export const isProtonSender = (
+    element: Element,
+    recipient: Recipient,
+    displayRecipients: boolean
+): boolean => {
+    // If displayRecipients is true, we're showing recipients instead of senders
+    // In this case, we check if the recipient is from Proton
+    if (displayRecipients) {
+        // For now, we don't have a way to check if a recipient is from Proton
+        // This would require additional information from the recipient
+        return false;
+    }
+
+    // Check if the element itself is from Proton
+    if (isFromProton(element)) {
+        return true;
+    }
+
+    // Check if the specific recipient is from Proton
+    // This would require additional logic to check the recipient's address
+    // For now, we return false if the element is not from Proton
+    return false;
+};
+
+/**
+ * Check if an element is from Proton
+ * @param element The element to check
+ * @returns true if the element is from Proton
+ */
+const isFromProton = (element: Element): boolean => {
+    return !!element.IsProton;
+};

