diff --git a/packages/components/hooks/useCheckStatus.ts b/packages/components/hooks/useCheckStatus.ts
new file mode 100644
index 0000000000..614395b342
--- /dev/null
+++ b/packages/components/hooks/useCheckStatus.ts
@@ -0,0 +1,77 @@
+import { useEffect, useRef } from 'react';
+
+import { getTokenStatus } from '@proton/shared/lib/api/payments';
+
+import useApi from './useApi';
+
+const CHECK_INTERVAL = 10000; // 10 seconds
+const INITIAL_DELAY = 10000; // 10 seconds
+
+/**
+ * Hook to check the status of a payment token
+ * @param token - The payment token to check
+ * @param enabled - Whether to enable the check
+ * @param onChargeable - Callback when the token becomes chargeable
+ */
+export const useCheckStatus = (
+    token: string | undefined,
+    enabled: boolean = false,
+    onChargeable?: (token: string, cryptoAmount: number, cryptoAddress: string) => void
+) => {
+    const api = useApi();
+    const isMountedRef = useRef(true);
+
+    useEffect(() => {
+        isMountedRef.current = true;
+
+        if (!enabled || !token) {
+            return;
+        }
+
+        let timeoutId: number | undefined;
+        let aborted = false;
+
+        const checkStatus = async () => {
+            if (aborted || !isMountedRef.current) {
+                return;
+            }
+
+            try {
+                const { Status } = await api({ ...getTokenStatus(token) });
+
+                if (aborted || !isMountedRef.current) {
+                    return;
+                }
+
+                if (Status === 1) {
+                    // STATUS_CHARGEABLE
+                    if (onChargeable) {
+                        // We need to get the amount and address from somewhere
+                        // For now, we'll pass empty values and let the caller handle it
+                        onChargeable(token, 0, '');
+                    }
+                } else if (Status === 0) {
+                    // STATUS_PENDING
+                    timeoutId = window.setTimeout(checkStatus, CHECK_INTERVAL);
+                }
+                // Other statuses (FAILED, CONSUMED, NOT_SUPPORTED) will just stop checking
+            } catch (error) {
+                // Silently handle errors and continue polling
+                if (isMountedRef.current) {
+                    timeoutId = window.setTimeout(checkStatus, CHECK_INTERVAL);
+                }
+            }
+        };
+
+        // Wait for initial delay before first check
+        timeoutId = window.setTimeout(checkStatus, INITIAL_DELAY);
+
+        return () => {
+            aborted = true;
+            isMountedRef.current = false;
+            if (timeoutId) {
+                clearTimeout(timeoutId);
+            }
+        };
+    }, [token, enabled, onChargeable, api]);
+};
