+import { CSSProperties } from 'react';
+
+export enum DropdownSizeUnit {
+    Viewport = 'viewport',
+    Static = 'static',
+    Dynamic = 'dynamic',
+    Anchor = 'anchor',
+}
+
+export interface DropdownSize {
+    width?: DropdownSizeUnit | string;
+    height?: DropdownSizeUnit | string;
+    maxWidth?: DropdownSizeUnit | string;
+    maxHeight?: DropdownSizeUnit | string;
+}
+
+/**
+ * Resolves the max-size CSS value.
+ * Returns `'initial'` if value is `DropdownSizeUnit.Viewport`,
+ * returns the unit string unchanged if valid, or `undefined` if not provided.
+ */
+export const getMaxSizeValue = (
+    value: DropdownSize['maxWidth'] | DropdownSizeUnit | string | undefined
+): string | undefined => {
+    if (value === undefined) {
+        return undefined;
+    }
+    if (value === DropdownSizeUnit.Viewport) {
+        return 'initial';
+    }
+    if (typeof value === 'string') {
+        return value;
+    }
+    return undefined;
+};
+
+/**
+ * Resolves a dropdown width based on the provided size.
+ * Uses anchor width for `Anchor`, content width for `Static`,
+ * passes through custom unit values, or `undefined` for `Dynamic` or missing rects.
+ */
+export const getWidthValue = (
+    width: DropdownSize['width'] | undefined,
+    anchorRect: DOMRect | null | undefined,
+    contentRect: DOMRect | null | undefined
+): string | undefined => {
+    if (width === undefined) {
+        return undefined;
+    }
+    if (typeof width === 'string') {
+        return width;
+    }
+    switch (width) {
+        case DropdownSizeUnit.Anchor:
+            return anchorRect?.width !== undefined ? `${anchorRect.width}px` : undefined;
+        case DropdownSizeUnit.Static:
+            return contentRect?.width !== undefined ? `${contentRect.width}px` : undefined;
+        case DropdownSizeUnit.Dynamic:
+        case DropdownSizeUnit.Viewport:
+            return undefined;
+        default:
+            return undefined;
+    }
+};
+
+/**
+ * Resolves dropdown height.
+ * Uses content height for `Static`, passes through unit strings,
+ * or `undefined` for `Dynamic`/missing rects.
+ */
+export const getHeightValue = (
+    height: DropdownSize['height'] | undefined,
+    anchorRect: DOMRect | null | undefined,
+    contentRect: DOMRect | null | undefined
+): string | undefined => {
+    if (height === undefined) {
+        return undefined;
+    }
+    if (typeof height === 'string') {
+        return height;
+    }
+    switch (height) {
+        case DropdownSizeUnit.Static:
+            return contentRect?.height !== undefined ? `${contentRect.height}px` : undefined;
+        case DropdownSizeUnit.Dynamic:
+        case DropdownSizeUnit.Viewport:
+        case DropdownSizeUnit.Anchor:
+            return undefined;
+        default:
+            return undefined;
+    }
+};
+
+/**
+ * Produces a CSS variable mapping (e.g., `{ "--width": "20px" }`) if a value is provided,
+ * otherwise returns `undefined`.
+ */
+export const getProp = (prop: string, value: string | undefined): Record<string, string> | undefined => {
+    if (value === undefined) {
+        return undefined;
+    }
+    return { [prop]: value };
+};
+
+/**
+ * Converts a DropdownSize object to CSS variables.
+ */
+export const getSizeCSSVariables = (
+    size: DropdownSize | undefined,
+    anchorRect: DOMRect | null | undefined,
+    contentRect: DOMRect | null | undefined
+): CSSProperties => {
+    if (!size) {
+        return {};
+    }
+
+    const width = getWidthValue(size.width, anchorRect, contentRect);
+    const height = getHeightValue(size.height, anchorRect, contentRect);
+    const maxWidth = getMaxSizeValue(size.maxWidth);
+    const maxHeight = getMaxSizeValue(size.maxHeight);
+
+    return {
+        ...(getProp('--width', width) ?? {}),
+        ...(getProp('--height', height) ?? {}),
+        ...(getProp('--max-width', maxWidth) ?? {}),
+        ...(getProp('--max-height', maxHeight) ?? {}),
+    };
+};

