+/**
+ * Replaces proton.black URLs with proton.local URLs when running in a local-sso environment.
+ * 
+ * @param href - The URL to potentially replace
+ * @returns The rewritten URL if in local-sso environment and URL contains proton.black, otherwise the original URL
+ * @throws TypeError if the input is not a valid absolute URL
+ */
+export const replaceLocalURL = (href: string): string => {
+    // Check if we're in a local-sso environment
+    const isLocalSSO = window.location.hostname.endsWith('.proton.local');
+    
+    if (!isLocalSSO) {
+        return href;
+    }
+    
+    // Try to parse the URL
+    let url;
+    try {
+        url = new URL(href);
+    } catch (e) {
+        // If it's not a valid URL, re-throw the TypeError
+        throw e;
+    }
+    
+    // Check if the URL's host ends with proton.black
+    // If it already ends with proton.local, return unchanged (idempotence)
+    if (!url.hostname.endsWith('.proton.black')) {
+        return href;
+    }
+    
+    // Get the current window's port
+    const currentPort = window.location.port;
+    
+    // Extract the subdomain from the input URL
+    // For example: drive.env.proton.black -> drive.env
+    //              drive-api.proton.black -> drive-api
+    //              drive.proton.black -> drive
+    const inputSubdomain = url.hostname.replace(/\.proton\.black$/, '');
+    
+    // Remove environment labels from subdomain (e.g., .env from drive.env)
+    // This handles cases like drive.env.proton.black -> drive.proton.local
+    const serviceSubdomain = inputSubdomain.replace(/\.env$/, '');
+    
+    // Set the new hostname
+    url.hostname = serviceSubdomain + '.proton.local';
+    
+    // Set the port if present
+    if (currentPort) {
+        url.port = currentPort;
+    }
+    
+    return url.href;
+};

