+
+/**
+ * Removes technical fields from an entity and its nested objects.
+ * This function mutates the input entity by recursively deleting all properties starting with
+ * `"_finalEncrypted"`, `"_defaultEncrypted"`, or `"_errors"`.
+ * These fields should not be carried over to new entity instances.
+ *
+ * @param entity The entity to clean up (will be mutated)
+ */
+export function removeTechnicalFields<E extends SomeEntity>(entity: E): void {
+	if (entity == null || typeof entity !== "object") {
+		return
+	}
+
+	// Remove technical fields at the current level
+	for (const key in entity) {
+		if (Object.prototype.hasOwnProperty.call(entity, key)) {
+			if (key.startsWith("_finalEncrypted") || key.startsWith("_defaultEncrypted") || key.startsWith("_errors")) {
+				// Cast to any to allow deletion of properties
+				delete (entity as any)[key]
+			} else {
+				// Recursively process nested objects and arrays
+				const value = (entity as any)[key]
+				if (value != null && typeof value === "object") {
+					if (Array.isArray(value)) {
+						// Process each element in the array
+						for (const item of value) {
+							if (item != null && typeof item === "object") {
+								removeTechnicalFields(item)
+							}
+						}
+					} else if (value instanceof Date || value instanceof Uint8Array || value instanceof TypeRef) {
+						// Skip these types as they don't have nested properties to process
+					} else {
+						// Process nested object
+						removeTechnicalFields(value as SomeEntity)
+					}
+				}
+			}
+		}
+	}
+}

